 1	/* 
 2	* Formal verification of a simple algorithm to find the maximum value in an array.
 3	* FEUP, MIEIC, MFES, 2020/21.
 4	*/
 5	
 6	// Finds the maximum value in a non-empty array.
 7	method findMax(a: array<real>) returns (max: real)
 8	  requires a.Length > 0
 9	  ensures exists k :: 0 <= k < (a.Length) - 1 && max == a[k]
10	  ensures forall k :: 0 <= k < a.Length ==> max >= a[k]
11	{
12	    max := a[0];
13	    for i := 1 to a.Length
14	      invariant exists k :: 0 <= k < i && max == a[k]
15	      invariant forall k :: 0 <= k < i ==> max >= a[k]
16	    {
17	        if (a[i] > max) {
18	            max := a[i];
19	        }
20	    } 
21	}
22	
23	
24	// Test cases checked statically.
25	method testFindMax() {
26	    var a1 := new real[3] [1.0, 2.0, 3.0]; // sorted asc
27	    var m1 := findMax(a1);
28	    assert m1 == a1[2] == 3.0;
29	
30	    var a2 := new real[3] [3.0, 2.0, 1.0]; // sorted desc
31	    var m2 := findMax(a2);
32	    assert m2 == a2[0] == 3.0;
33	
34	    var a3 := new real[3] [2.0, 3.0, 1.0]; // unsorted
35	    var m3 := findMax(a3);
36	    assert m3 == a3[1] == 3.0;
37	
38	    var a4 := new real[3] [1.0, 2.0, 2.0]; // duplicates
39	    var m4 := findMax(a4);
40	    assert m4 == a4[1] == 2.0;
41	
42	    var a5 := new real[1] [1.0]; // single element
43	    var m5 := findMax(a5);
44	    assert m5 == a5[0] == 1.0;
45	
46	    var a6 := new real[3] [1.0, 1.0, 1.0]; // all equal
47	    var m6 := findMax(a6);
48	    assert m6 == a6[0] == 1.0;
49	    
50	}
